llamadas.contenido:
{
  "title": "Reserva e ingreso de ejemplares en la Biblioteca Municipal de Villaficticia",
  "role": "Persona socia de la biblioteca",
  "action": "quiero reservar un ejemplar y recogerlo en el mostrador",
  "benefit": "Tengo el acceso a materiales de lectura y el deseo de disfrutarlo en mi propio tiempo",
  "description": "Como persona socia, quisiera poder reservar los ejemplares que me interesan a través del sitio web de la biblioteca, recogerlos en el mostrador de mi elección, y asegurarme de cumplir con los protocolos de la biblioteca mientras aprovecho de forma responsable la oferta de préstamo proporcionada.",
  "business_goal": "Maximizar el uso eficiente de los recursos de la biblioteca mientras cumplimos con las políticas de la entidad",
  "scope_includes": [
    "Reserva de ejemplares a través del sitio web de la biblioteca",
    "Recogida de ejemplares en el mostrador preferido",
    "Cumplimiento de los protocolos de la biblioteca",
    "Uso responsable de los recursos de la biblioteca"
  ],
  "scope_excludes": [
    "Prestamos en línea",
    "Reservas fuera del número máximo permitido",
    "Colegio para menores"
  ],
  "acceptance_criteria": [
    {
      "id": "CA-01",
      "title": "Reserva es posible siguiendo las reglas de negocio establecidas",
      "given": [
        "Soy una persona socia de la biblioteca con carné válido",
        "No tengo sanciones activas que impidan reservar"
      ],
      "when": [
        "Realizo una reserva según las reglas del proceso de reserva"
      ],
      "then": [
        "La reserva se efectúa correctamente y queda reflejada en el sistema"
      ]
    },
    {
      "id": "CA-02",
      "title": "Número máximo de reservas se mantiene",
      "given": [
        "Actualmente tengo reservados ejemplares",
        "Tengo más de 3 reservas activas"
      ],
      "when": [
        "Intento reservar un nuevo ejemplar"
      ],
      "then": [
        "El sistema rechaza la reserva, informándome del límite de 3 reservas"
      ]
    },
    {
      "id": "CA-03",
      "title": "Reseña de las políticas de las obras de referencia",
      "given": [
        "Yo soy una persona socia de la biblioteca"
      ],
      "when": [
        "Intento reservar una obra de referencia"
      ],
      "then": [
        "La reserva es rechazada debido al artículo 9 del Reglamento de préstamo"
      ]
    }
  ],
  "business_rules": [
    {
      "id": "RN-RES-01",
      "description": "Reserva solo posible para personas socias con carné válido y sin sanción activa impidiéndola (resolución RN-SAN-03 y RN-SAN-04 en DOC-03)"
    },
    {
      "id": "RN-RES-02",
      "description": "Cada persona socia puede hacer un máximo de 3 reservas activas (reservas en estado \"pendiente\" o \"disponible para recoger\")"
    },
    {
      "id": "RN-RES-06",
      "description": "Si el ejemplar no se recoge en 48 horas, la reserva caduca y el ejemplar pasa a la siguiente persona (política de RN-SAN-04 revisada CONVención DOC-20)"
    },
    {
      "id": "RN-RES-09",
      "description": "Personas con carné infantil solo pueden reservar obras de la colección infantil y juvenil (con el límite de 3 reservas activas)"
    },
    {
      "id": "RN-RES-01",
      "description": "Número máximo de ejemplares simultáneamente varía según la categoría del material (8 ejemplares por persona socia general y 4 para menores de la colección infantil y juvenil, por ejemplo, como se indica en el DOC-01)"
    }
  ],
  "assumptions": [
    "Tengo acceso al sitio web oficial de la biblioteca para realizar reservas.",
    "Soy una persona legalmente reconocida como socia de la biblioteca Municipal de Villaficticia."
  ],
  "constraints": [
    "Necesito cumplir con las políticas de préstamo impuestas, incluyendo la numeración máxima de ejemplares.",
    "Debo adherirme a los límites de préstamo, especialmente si soy una persona con carné infantil."
  ],
  "dependencies": [
    "El proceso de reserva depende de la versión actualizada del Circuito de reserva y recogida (DOC-06, versión 3, 2026-05-05).",
    "El número de reservas no recogidas es una consideración adicional influenciando los protocolos de reserva (DOC-20)."
  ],
  "alternate_flows": [
    "Si mi reserva no se recoge en 48 horas, busco otra obra que cumpla con mis necesidades."
  ],
  "exceptions": [
    "Las reservas de obras de referencia y títulos ya con ejemplar en préstamo son inacepables."
  ],
  "related_features": [
    "Acceso a múltiples colecciones (libros, audiovisuales, revistas, libros electrónicos y obras de referencia)"
  ],
  "priority": "Must",
  "sources": [
    {
      "kind": "rag",
      "ref": "DOC-02"
    },
    {
      "kind": "rag",
      "ref": "DOC-06"
    },
    {
      "kind": "rag",
      "ref": "DOC-01"
    },
    {
      "kind": "rag",
      "ref": "DOC-20"
    }
  ],
  "open_questions": [
    "¿Cómo se manejará una reserva no recogida reiterada para que no perjudique el uso del ejemplar para otras personas socias?",
    "¿Existen políticas de préstamo especiales para las categorías no relacionadas con obras de referencia, tales como audiovisuales o libros electrónicos?"
  ]
}
